const EXPERT_COUNT=EXPERT_FAMILIES.length*32768;
const expertCache=new Map();
function buildExpert(id,families,axes,start){
 let k=id-start;const family=Math.floor(k/32768),f=families[family];if(!f)return null;k%=32768;
 const digits=Array.from({length:5},()=>{const d=k%8;k=Math.floor(k/8);return d;});
 const context=digits.map((d,i)=>axes[i][d]);const shift=(family+digits.reduce((a,b)=>a+b,0))%3;
 const opts=f.options.slice(shift).concat(f.options.slice(0,shift));
 return {family,level:f.level,data:[f.cat,f.title,`${context[0]} ${f.story} ${context.slice(1).join(" ")}`,opts.map(o=>[o.title,o.desc,o.effect,o.q===2?"réfléchi":"choix à nuancer"])],qualities:opts.map(o=>o.q),feedback:opts.map(o=>o.feedback),echoes:opts.map(o=>[[f.title,(/^Souvenez-vous/.test(o.echo)?o.echo:`Souvenez-vous : ${o.title.toLowerCase()}. ${o.echo}`),o.delta,"Les conséquences d'une décision ne se révèlent pas toujours immédiatement."]])};
}
function expertOrder(random,seen,start,count){
 const n=count/32768,blocked=new Set(seen),recent=new Set(seen.slice(-20).filter(id=>id>=start&&id<start+count).map(id=>Math.floor((id-start)/32768)));
 let available=Array.from({length:n},(_,i)=>i).filter(i=>!recent.has(i));
 if(available.length<10)available=Array.from({length:n},(_,i)=>i);
 const order=[];
 for(let i=0;i<10;i++){
  const j=Math.floor(random()*available.length),f=available.splice(j,1)[0];let v=Math.floor(random()*32768);
  while(blocked.has(start+f*32768+v))v=(v+1)%32768;
  const id=start+f*32768+v;order.push(id);blocked.add(id);
 }return order;
}
function expertAt(id){if(!Number.isInteger(id)||id<EXPERT_START||id>=EXPERT_START+EXPERT_COUNT)return null;if(!expertCache.has(id)){if(expertCache.size>=128)expertCache.delete(expertCache.keys().next().value);expertCache.set(id,buildExpert(id,EXPERT_FAMILIES,EXPERT_AXES,EXPERT_START));}return expertCache.get(id);}
if(SITUATIONS.length!==EXPERT_START)throw new Error('Identifiants historiques incompatibles');
SITUATIONS=new Proxy(SITUATIONS,{get(target,key,receiver){if(key==='length')return EXPERT_START+EXPERT_COUNT;if(typeof key==='string'&&/^\d+$/.test(key)){const id=Number(key);if(id>=EXPERT_START)return expertAt(id)?.data;}return Reflect.get(target,key,receiver);}});
